import { Schema, model, type HydratedDocument, type InferSchemaType } from 'mongoose';
import type { ClothingCategory, ClothingItemResponse } from './clothingItem.js';

// 'manual' outfits are built by the user; 'ai' outfits are generated by the app.
export const OUTFIT_SOURCES = ['manual', 'ai'] as const;

export const OUTFIT_OCCASIONS = ['casual', 'work', 'formal', 'workout'] as const;
export type OutfitOccasion = (typeof OUTFIT_OCCASIONS)[number];

export const OUTFIT_LIMITS = {
  nameLength: 100,
  occasionLength: 100,
  maxItems: 20,
} as const;

// Most items of each category one outfit can have. Two tops allow layering; one of everything
// else keeps an outfit wearable. `phrase` finishes "An outfit can have at most ...".
export const OUTFIT_CATEGORY_LIMITS: Record<ClothingCategory, { max: number; phrase: string }> = {
  top: { max: 2, phrase: '2 tops' },
  bottom: { max: 1, phrase: '1 bottom' },
  outerwear: { max: 1, phrase: '1 outerwear piece' },
  dress: { max: 1, phrase: '1 dress' },
  shoes: { max: 1, phrase: '1 pair of shoes' },
  accessory: { max: 3, phrase: '3 accessories' },
};

const outfitSchema = new Schema(
  {
    owner: { type: Schema.Types.ObjectId, ref: 'User', required: true },
    name: { type: String, required: true, trim: true, maxlength: OUTFIT_LIMITS.nameLength },
    occasion: { type: String, trim: true, maxlength: OUTFIT_LIMITS.occasionLength, default: '' },
    items: [{ type: Schema.Types.ObjectId, ref: 'ClothingItem' }],
    source: { type: String, enum: OUTFIT_SOURCES, default: 'manual' },
  },
  { timestamps: true }
);

outfitSchema.index({ owner: 1, createdAt: -1 });
outfitSchema.index({ items: 1 });

export type OutfitDocument = HydratedDocument<InferSchemaType<typeof outfitSchema>>;

export const Outfit = model('Outfit', outfitSchema);

export function saveOutfit(ownerId: string, name: string, itemIds: string[]): Promise<OutfitDocument> {
  return Outfit.create({ owner: ownerId, name, items: itemIds, source: 'manual' });
}

export interface OutfitResponse {
  id: string;
  name: string;
  occasion: string;
  source: string;
  items: ClothingItemResponse[];
  createdAt: Date;
  updatedAt: Date;
}

// Takes the outfit's items already shaped for the app; items that no longer exist are left out.
export function toOutfitResponse(outfit: OutfitDocument, items: ClothingItemResponse[]): OutfitResponse {
  return {
    id: outfit._id.toString(),
    name: outfit.name,
    occasion: outfit.occasion,
    source: outfit.source,
    items,
    createdAt: outfit.createdAt,
    updatedAt: outfit.updatedAt,
  };
}
